3	import (
4		"encoding/json"
5		"log"
6		"os"
7		"path/filepath"
8		"sync"
9	)
10	
11	// What the browser remembers between visits is which registries were
12	// **un**checked, not which were checked. A group discovered since the last
13	// visit therefore arrives selected like every other new entry, instead of
14	// silently sitting out of every search because it did not exist when the
15	// selection was saved.
16	//
17	// Kept per context, because registries are.
18	
19	// BrowserSelectionCache remembers the registries excluded from the browser
20	// search, per configuration context.
21	type BrowserSelectionCache struct {
22		mu       sync.RWMutex
23		path     string
24		excluded map[string][]string // context name → entry URLs left unchecked
25	}
26	
27	// NewBrowserSelectionCache creates or loads the cache from
28	// ~/.devdesk/cache/browser-selection.json
29	func NewBrowserSelectionCache() (*BrowserSelectionCache, error) {
30		homeDir, err := os.UserHomeDir()
31		if err != nil {
32			return nil, err
33		}
34	
35		cacheDir := filepath.Join(homeDir, ".devdesk", "cache")
36		if err := os.MkdirAll(cacheDir, 0755); err != nil {
37			return nil, err
38		}
39	
40		c := &BrowserSelectionCache{
41			path:     filepath.Join(cacheDir, "browser-selection.json"),
42			excluded: make(map[string][]string),
43		}
44	
45		c.load()
46		return c, nil
47	}
48	
49	func (c *BrowserSelectionCache) load() {
50		data, err := os.ReadFile(c.path)
51		if err != nil {
52			return
53		}
54		if err := json.Unmarshal(data, &c.excluded); err != nil {
55			log.Printf("ERROR [cache/browser_selection] unmarshal cache file %s: %v", c.path, err)
56		}
57	}
58	
59	func (c *BrowserSelectionCache) save() error {
60		data, err := json.MarshalIndent(c.excluded, "", "  ")
61		if err != nil {
62			return err
63		}
64		return os.WriteFile(c.path, data, 0600)
65	}
66	
67	// Deselected returns the entry URLs left unchecked in a context, as a set.
68	func (c *BrowserSelectionCache) Deselected(context string) map[string]bool {
69		c.mu.RLock()
70		defer c.mu.RUnlock()
71		out := make(map[string]bool, len(c.excluded[context]))
72		for _, url := range c.excluded[context] {
73			out[url] = true
74		}
75		return out
76	}
77	
78	// SetDeselected records the entry URLs left unchecked in a context. An empty
79	// list removes the context rather than storing one, so a file that nobody has
80	// excluded anything in stays empty.
81	func (c *BrowserSelectionCache) SetDeselected(context string, urls []string) error {
82		c.mu.Lock()
83		defer c.mu.Unlock()
84		if len(urls) == 0 {
85			delete(c.excluded, context)
86		} else {
87			c.excluded[context] = urls
88		}
89		return c.save()
90	}
