13	// InEditMode returns true when a text input is active (blocks command mode).
14	func (b *RegistryBrowser) InEditMode() bool {
15		if b.state == browserStateInput && b.focusedField == brFieldRepo {
16			return true
17		}
18		return b.state == browserStateTags && b.filterActive
19	}
20	
21	// IsSearching returns true while registry tag queries are still in flight.
22	func (b *RegistryBrowser) IsSearching() bool {
23		return b.pendingSearches > 0
24	}
