26	// Update handles all messages for the browser.
27	func (b *RegistryBrowser) Update(msg tea.Msg) (*RegistryBrowser, tea.Cmd) {
28		switch msg := msg.(type) {
29		case tea.KeyMsg:
30			return b.handleKeyMsg(msg)
31		case spinner.TickMsg:
32			if b.state == browserStateStatus || len(b.scanningTags) > 0 || b.pendingSearches > 0 {
33				var cmd tea.Cmd
34				b.spinner, cmd = b.spinner.Update(msg)
35				if b.state == browserStateTags && len(b.scanningTags) > 0 {
36					b.tagScanSpinnerIdx++
37					b.rebuildTagTable()
38				}
39				return b, cmd
40			}
41			return b, nil
42		}
43		return b.delegateUpdate(msg)
44	}
45	
46	func (b *RegistryBrowser) delegateUpdate(msg tea.Msg) (*RegistryBrowser, tea.Cmd) {
47		if b.state == browserStateInput && b.focusedField == brFieldRepo {
48			var cmd tea.Cmd
49			b.repoInput, cmd = b.repoInput.Update(msg)
50			return b, cmd
51		}
52		if b.state == browserStateTags {
53			if b.filterActive {
54				var cmd tea.Cmd
55				b.filterInput, cmd = b.filterInput.Update(msg)
56				b.rebuildTagTable()
57				return b, cmd
58			}
59			var cmd tea.Cmd
60			b.tagTable, cmd = b.tagTable.Update(msg)
61			return b, cmd
62		}
63		return b, nil
64	}
