112	// credsFor returns the credentials to search entry with, and nothing at all
113	// when the registry — or the group it belongs to — is marked anonymous (D12).
114	// Docker keys credentials by host, so a Nexus instance with one repository
115	// logged into would otherwise send that login to every repository it serves.
116	func (b *RegistryBrowser) credsFor(entry browserRegistryEntry) (string, string) {
117		if !config.UsesCredentials(entry.authMode) {
118			return "", ""
119		}
120		// Credentials come from the parent registry, or the entry itself for a
121		// registry that is not a group member.
122		credURL := entry.URL
123		if entry.parentURL != "" {
124			credURL = entry.parentURL
125		}
126		var username string
127		for _, reg := range b.registries {
128			if reg.URL == credURL {
129				username = reg.Username
130				break
131			}
132		}
133		storedUser, storedPass, _ := docker.GetStoredCreds(credURL)
134		if username == "" {
135			username = storedUser
136		}
137		return username, storedPass
138	}
