140	func (b *RegistryBrowser) submitSearch() (*RegistryBrowser, tea.Cmd) {
141		repo := strings.TrimSpace(b.repoInput.Value())
142		if repo == "" {
143			return b, nil
144		}
145	
146		b.tags = nil
147		b.registryFilter = resultFilter{}
148		b.pendingSearches = 0
149		b.filterInput.SetValue("")
150		b.filterActive = false
151		b.tagSortCol = tagSortByName
152		b.tagSortDesc = false
153	
154		var cmds []tea.Cmd
155		for _, entry := range b.entries {
156			if !b.selectedRegs[entry.URL] {
157				continue
158			}
159			username, storedPass := b.credsFor(entry)
160			alias := entry.Alias
161			if entry.ParentAlias != "" {
162				alias = entry.ParentAlias + "/" + entry.Alias
163			}
164			normalizedRepo := normalizeRepoForRegistry(entry.URL, repo)
165			apiURL := registryAPIURL(entry.URL)
166			b.pendingSearches++
167			cmds = append(cmds, searchRegistryTagsCmd(entry.URL, alias, apiURL, normalizedRepo, username, storedPass))
168		}
169	
170		if len(cmds) == 0 {
171			return b, nil
172		}
173	
174		b.state = browserStateTags
175		b.tagTable.Focus()
176		b.rebuildTagTable()
177		cmds = append(cmds, b.spinner.Tick)
178		return b, tea.Batch(cmds...)
179	}
