181	func (b *RegistryBrowser) handleTagsKeyMsg(msg tea.KeyMsg) (*RegistryBrowser, tea.Cmd) {
182		if b.filterActive {
183			switch msg.String() {
184			case "esc", "enter":
185				b.filterActive = false
186				b.filterInput.Blur()
187				b.rebuildTagTable()
188				b.resizeTagTable()
189				return b, nil
190			}
191			return b.delegateUpdate(msg)
192		}
193	
194		switch msg.String() {
195		case "esc":
196			b.state = browserStateInput
197			b.tagTable.Blur()
198			b.updateFocus()
199			return b, nil
200		case "/":
201			b.filterActive = true
202			b.filterInput.Focus()
203			b.resizeTagTable()
204			return b, nil
205		case ".":
206			b.cycleSortTags()
207			return b, nil
208		case "r":
209			b.cycleRegistryFilter()
210			return b, nil
211		case "up", "k":
212			b.tagTable.MoveUp(1)
213			return b, nil
214		case "down", "j":
215			b.tagTable.MoveDown(1)
216			return b, nil
217		case "g", "home":
218			b.tagTable.GotoTop()
219			return b, nil
220		case "G", "end":
221			b.tagTable.GotoBottom()
222			return b, nil
223		case "enter":
224			return b.openTagScanDetails()
225		case "p":
226			return b.pullSelectedTag()
227		case "ctrl+s":
228			return b.requestDirectScan()
229		}
230		return b, nil
231	}
