82	func (b *RegistryBrowser) viewInput() string {
83		var sb strings.Builder
84	
85		sb.WriteString(theme.EmptyLineBg(b.width) + "\n")
86		sb.WriteString(b.renderInputField("Repository", b.repoInput.View(), brFieldRepo))
87		sb.WriteString("\n\n")
88	
89		if len(b.rows) > 0 {
90			sb.WriteString(theme.Bg("  ") + theme.DimStyle.Render("Registries:") + "\n")
91			for i, row := range b.rows {
92				focused := b.focusedField == b.brFieldReg(i)
93				if row.groupSlug != "" {
94					// One checkbox for the whole group, with a third state for a
95					// partial selection — eight proxies are not eight keystrokes.
96					sb.WriteString(theme.RenderCheckboxTri(b.groupState(row.groupSlug), row.label, focused))
97				} else {
98					sb.WriteString(theme.RenderCheckbox(b.selectedRegs[b.entries[row.entry].URL], row.label, focused))
99				}
100				if i < len(b.rows)-1 {
101					sb.WriteString("\n")
102				}
103			}
104			sb.WriteString("\n\n")
105		}
106	
107		sb.WriteString("  ")
108		sb.WriteString(theme.RenderButton("Browse Tags", b.focusedField == b.brFieldSubmit(), "primary"))
109	
110		return sb.String()
111	}
