113	func (b *RegistryBrowser) renderInputField(label, value string, fieldIdx int) string {
114		var labelStr string
115		if b.focusedField == fieldIdx {
116			labelStr = theme.KeyStyle.Render(theme.IconCircleSmall + " " + label + " " + theme.IconChevronRight)
117		} else {
118			labelStr = theme.Bg("  " + label + " " + theme.IconChevronRight)
119		}
120		return labelStr + "\n  " + value
121	}
