123	func (b *RegistryBrowser) viewTags() string {
124		displayed := b.filteredSortedMultiTags()
125		if len(displayed) == 0 {
126			if b.pendingSearches > 0 {
127				return theme.EmptyLineBg(b.width) + "\n" +
128					theme.SpinnerMessage(b.spinner.View(), "Searching registries...")
129			}
130			return theme.DimStyle.Render("  No tags found")
