135	// FilterIsVisible returns true when the tag filter bar should be shown in the footer.
136	func (b *RegistryBrowser) FilterIsVisible() bool {
137		return b.state == browserStateTags && (b.filterActive || b.filterInput.Value() != "" || !b.registryFilter.isEmpty())
