140	// FilterBarView renders the filter bar (2 lines) for display in the footer.
141	func (b *RegistryBrowser) FilterBarView(width int) string {
142		borderStyle := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)
143	
144		var left string
145		if b.filterActive {
146			left = theme.KeyStyle.Render("/") + theme.Bg(" ") + b.filterInput.View()
147		} else if b.filterInput.Value() != "" {
148			left = theme.DimStyle.Render("/ ") + theme.KeyStyle.Render(b.filterInput.Value())
149		} else {
150			left = theme.DimStyle.Render("/ filter…")
151		}
152	
153		if !b.registryFilter.isEmpty() {
154			left += theme.Bg("  ") + theme.KeyStyle.Render("["+b.registryFilterLabel()+"]")
155		}
156	
157		inner := theme.Bg(" ") + left
158		paddedInner := theme.PadWithBg(inner, width-2)
159		contentLine := borderStyle.Render("│") + paddedInner + borderStyle.Render("│")
160		bottomBorder := borderStyle.Render("└" + strings.Repeat("─", width-2) + "┘")
161		return contentLine + "\n" + bottomBorder
162	}
