25	// filterStops returns the values `r` cycles through: every group that produced
26	// results, then every individual registry, then off. The group level is what
27	// makes "everything from this Nexus" one keystroke rather than eight.
28	func (b *RegistryBrowser) filterStops() []resultFilter {
29		seenGroup, seenURL := map[string]bool{}, map[string]bool{}
30		var groups, singles []resultFilter
31		for _, t := range b.tags {
32			entry := b.entryFor(t.RegistryURL)
33			if entry != nil && entry.ParentSlug != "" && !seenGroup[entry.ParentSlug] {
34				seenGroup[entry.ParentSlug] = true
35				groups = append(groups, resultFilter{groupSlug: entry.ParentSlug})
36			}
37			if !seenURL[t.RegistryURL] {
38				seenURL[t.RegistryURL] = true
39				singles = append(singles, resultFilter{url: t.RegistryURL})
40			}
41		}
42		// A single source has nothing to filter down to.
43		if len(singles) <= 1 {
44			return nil
45		}
46		// A group with every result under it says the same thing as "off".
47		if len(groups) == 1 && len(groups) == len(seenGroup) && len(singles) == countMembers(b.entries, groups[0].groupSlug) {
48			groups = nil
49		}
50		return append(groups, singles...)
51	}
