13	// getSelectedRegistry returns a pointer to the selected registry item, or nil —
14	// including inside a group, where the rows are cached members rather than
15	// config entries and nothing on them is editable.
16	func (m Model) getSelectedRegistry() *config.RegistryItem {
17		if m.registryGroupSlug != "" {
18			return nil
19		}
20		cursor := m.registryTable.Cursor()
21		if cursor < 0 || cursor >= len(m.registries) {
22			return nil
23		}
24		return &m.registries[cursor]
25	}
