27	// enterSelectedGroup drills into the selected group (Rule 111: → goes down a
28	// level). A group with nothing discovered has no level to enter.
29	func (m Model) enterSelectedGroup() (tea.Model, tea.Cmd) {
30		reg := m.getSelectedRegistry()
31		if reg == nil || reg.Kind != config.KindGroup {
32			return m, nil
33		}
34		if len(m.groupCache[reg.Slug].Members) == 0 {
35			m.infoMsg = "No members discovered yet — press ctrl+r to look"
36			return m, clearInfoMsgCmd()
37		}
38		m.registryGroupSlug = reg.Slug
39		m.updateRegistryTable()
40		m.registryTable.GotoTop()
41		return m, nil
42	}
